import{_ as i,l,o as e,c as o,v as t,p as n,x as r,d as h,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"A* 与启发式搜索","description":"","frontmatter":{"title":"A* 与启发式搜索","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/a-star.md","filePath":"cs/a-star.md","lastUpdated":1789023840000}'),c={name:"cs/a-star.md"};function m(u,a,_,A,f,k){const s=l("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="a-与启发式搜索" tabindex="-1">A* 与启发式搜索 <a class="header-anchor" href="#a-与启发式搜索" aria-label="Permalink to &quot;A* 与启发式搜索&quot;">​</a></h1><div class="epigraph"><p>$f(n)=g(n)+h(n)$：已付代价加到达目标的估计；一致启发下 A* 展开的结点不超过任何同等启发的最优搜索。</p><footer>—— 据 Hart, Nilsson and Raphael, A Formal Basis for the Heuristic Determination of Minimum Cost Paths, 1968；Dijkstra 1959 对照整理</footer></div><p>上一课<a href="/cs/graph-isomorphism">图同构直觉</a>收束连通与匹配单元。主干<a href="/cs/dijkstra">Dijkstra</a>是 \\(h=0\\) 的最短路。本课缺口是<strong>启发式</strong> \\(h\\)：低估到 \\(t\\) 的距离时，优先队列按 \\(g+h\\) 取出仍正确。不重证非负权取出即钉死的那套，只把它改成带势的比较。后课双向与 ALT 把 \\(h\\) 造得更狠。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>状态图（网格、配置）上单源到 \\(t\\)。\\(g(n)\\) 为从 \\(s\\) 到 \\(n\\) 的已知代价。\\(h(n)\\) 估计 \\(n\\) 到 \\(t\\)。可采纳（admissible）：\\(h(n)\\le\\delta(n,t)\\)。一致（consistent）：\\(h(u)\\le w(u,v)+h(v)\\)。一致 \\(\\Rightarrow\\) 可采纳；此时 A* 与带势 Dijkstra 相同：\\(\\hat w(u,v)=w(u,v)+h(v)-h(u)\\ge 0\\)，按 \\(g+h\\) 取出即钉死。</p><p>缺口是 \\(h\\)，不是新的堆。\\(h=0\\) 即 Dijkstra。过高估计可能丢最优，变成贪心最佳优先搜索。</p><h3 id="启发来自松弛问题" tabindex="-1">启发来自松弛问题 <a class="header-anchor" href="#启发来自松弛问题" aria-label="Permalink to &quot;启发来自松弛问题&quot;">​</a></h3><p>网格用曼哈顿；图上用欧氏（若边权 \\(\\ge\\) 直线）。可采纳常来自删除约束后的真距离。不要把机器学习的启发式当本课正确性条件——除非仍可采纳。</p><p><span class="marginnote">Hart–Nilsson–Raphael 1968。Pearl 的启发式搜索书是后续。一致启发下不会 decrease-key 到已钉死结点（与 Dijkstra 同）。后课 ALT 用路标算 \\(h\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>优先队列键 \\(f=g+h\\)。取出 \\(u\\)，若 \\(u=t\\) 停（一致时）。松弛邻接，更新 \\(g\\) 与父指针。启发式预计算或闭式。</p>',11)),(e(),n(p,null,{default:r(()=>[d(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22s%22%5D%20--%3E%20G%5B%22g%20%E5%B7%B2%E4%BB%98%22%5D%0A%20%20H%5B%22h%20%E5%90%AF%E5%8F%91%22%5D%20--%3E%20F%5B%22f%3Dg%2Bh%20%E5%87%BA%E9%98%9F%22%5D%0A%20%20G%20--%3E%20F%0A%20%20F%20--%3E%20T%5B%22%E5%88%B0%E8%BE%BE%20t%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>不一致但可采纳时需允许重开结点，最坏仍可能指数展开，本课默认一致。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>势函数把原权变成非负，Dijkstra 正确性平移。展开结点集：任何 \\(f(n)\\lt \\delta(s,t)\\) 的 \\(n\\) 都必须展开，故 \\(h\\) 越大（仍可采纳）剪掉越多。与 DFS/BFS：无权且 \\(h=0\\) 不是 A* 的主场景；网格上 A* 典型。</p><p>不要在负权图上直接 A*：先 Bellman–Ford 或禁负。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 IDA*、不写 SMA*。不把博弈树的 \\(\\alpha\\beta\\) 当同一算法。后课默认：一致 \\(h\\) 下 A* 最优；实现是带势 Dijkstra。下一课双向搜索与 ALT 路标。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>可采纳 \\(h\\) 保证最优；一致则取出即钉死。</li><li>\\(h=0\\) 退回 Dijkstra；过大 \\(h\\) 丢最优。</li><li>启发来自松弛真距离。</li><li>出处：Hart, Nilsson and Raphael, 1968。</li></ul>',8))])}const g=i(c,[["render",m]]);export{B as __pageData,g as default};
